// Construye el texto que sera embebido (concatena los campos relevantes)
const item = $input.item.json;
const entregables = (item.entregables || []).join('. ');
const casos = (item.casos_uso || []).join('. ');
const prereqs = (item.prerequisitos || []).join('. ');

const textoEmbedding = [
  item.nombre,
  item.descripcion_corta,
  item.descripcion_larga,
  `Precio setup: ${item.precio_setup || 'no aplica'}`,
  `Precio recurrente: ${item.precio_recurrente || 'no aplica'}`,
  `Tiempo entrega: ${item.tiempo_entrega || 'no aplica'}`,
  `Entregables: ${entregables}`,
  `Casos de uso: ${casos}`,
  `Prerequisitos: ${prereqs}`
].filter(Boolean).join('\n');

return {
  ...item,
  texto_embedding: textoEmbedding
};

// Combina datos del servicio con el embedding generado
const servicio = $('Construir texto a embedear').item.json;
const embeddingResp = $input.item.json;
const embedding = embeddingResp.data?.[0]?.embedding;

if (!embedding) {
  throw new Error(`No se obtuvo embedding para ${servicio.slug}`);
}

return {
  slug: servicio.slug,
  categoria: servicio.categoria,
  nombre: servicio.nombre,
  descripcion_corta: servicio.descripcion_corta || null,
  descripcion_larga: servicio.descripcion_larga || null,
  precio_setup: servicio.precio_setup || null,
  precio_recurrente: servicio.precio_recurrente || null,
  tiempo_entrega: servicio.tiempo_entrega || null,
  entregables: servicio.entregables || [],
  casos_uso: servicio.casos_uso || [],
  prerequisitos: servicio.prerequisitos || [],
  embedding: '[' + embedding.join(',') + ']'
};
